import { Injectable } from '@nestjs/common';
import { createReadStream } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import type { Readable } from 'node:stream';
import { config } from '../../config';

/** Where file bytes live. Keys are opaque, generated by FilesService; they never contain user input. */
export interface StorageDriver {
  readonly name: string;
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  open(key: string): Promise<Readable>;
  remove(key: string): Promise<void>;
}

/** Dev/test driver: files under FILES_DIR. Production uses S3 (CD-15), added with the infra work. */
@Injectable()
export class LocalDiskStorage implements StorageDriver {
  readonly name = 'local';
  private readonly root = path.resolve(config().FILES_DIR);

  private resolve(key: string): string {
    if (!/^[a-z0-9][a-z0-9/_.-]*$/i.test(key) || key.includes('..')) throw new Error('Invalid storage key');
    const full = path.resolve(this.root, key);
    if (!full.startsWith(this.root + path.sep)) throw new Error('Storage key escapes root');
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    const tmp = `${full}.${randomUUID()}.tmp`;
    await fs.writeFile(tmp, data, { flag: 'wx' });
    await fs.rename(tmp, full); // atomic: readers never see a half-written file
  }

  async open(key: string): Promise<Readable> {
    const full = this.resolve(key);
    await fs.access(full);
    return createReadStream(full);
  }

  async remove(key: string): Promise<void> {
    await fs.rm(this.resolve(key), { force: true });
  }
}

export const STORAGE = Symbol('StorageDriver');
